/**
 * The lab code table: printed name → NČLP (and LOINC) code.
 *
 * `codes/lab-codes.json` is generated by tools/pipeline/scripts/
 * build_lab_codes.py from the Czech national code list (NČLP, MZ ČR / DASTA)
 * plus the curated links in `codes/curation.json`. A row is one NČLP item in
 * its method-independent form: a component, in a system (the specimen), as a
 * kind of quantity, in a unit. The key is the code; names live per language
 * under `names.<lang>` so a second language is a data change, not a schema one.
 *
 * Two questions this module answers, both without a model:
 *
 * - `lookup(name, unit, material)` — the deterministic step: the rows whose
 *   names normalise to the printed name (its full key, a trailing `[ABBR]`,
 *   a glued leading code, the parts around a parenthesis or " - "), ranked by
 *   how well specimen and unit agree. Empty when nothing matches.
 * - `shortlist(name, unit, material, n)` — the candidates a model picks from
 *   when lookup is empty or ambiguous: character-trigram similarity over every
 *   row's names, the same specimen and unit agreement as a tiebreak.
 *
 * Nothing here reads a value. The name, unit and specimen are the whole input,
 * so a shortlist can go to a model without a single patient number.
 * docs/plans/lab-codes.md has the sources, licences and the measured numbers.
 */
import type { AnalyteDef } from "./models";
import { canonicalizeUnit, materialPrefix } from "./normalize";
import { abbreviationKey, leadingCodeKey, normKey } from "./registry";

export interface LabCodeNames {
  /** The full item name, e.g. "Na (S; látková konc. [mmol/l])". */
  name: string;
  /** What a LIS derives from the code list: `S_Na`, `B_Neutrofily`. */
  printed?: string[];
  /** Short and long component names and curated synonyms (NČLP's own). */
  syn: string[];
  /**
   * What labs print for the component, lent by the catalog entries linked to
   * it ("Sodík", "Močovina", "GMT") — on every specimen of that component.
   */
  common?: string[];
  /** The kind of quantity in words ("Látková koncentrace"). */
  prop?: string;
  /** Only on a row NČLP has no method-independent form of: its procedure ("Výpočet"). */
  method?: string;
}

export interface LabCodeRow {
  /** NČLP key of the method-independent item (procedure `*`). */
  id: string;
  /** NČLP system code: S, P, B, U, DU, LKC(B), ERC(B)… */
  sys: string;
  /** NČLP component code: NA, GLU, NEU… */
  comp: string;
  /** Kind of quantity, LOINC-like short form: SCnc, MCnc, CCnc, NCnc, NFr, ACnc… */
  prop: string;
  /** NČLP unit as published ("1" = a fraction, "-" = none). */
  unit: string;
  /** The app's material prefix code: s, p, b, u, du. */
  mat: string;
  spec: string;
  /** NČLP component class (ELE, ENZ, HOR, BWBC…). */
  kind: string;
  names: Record<string, LabCodeNames>;
  npu?: string;
  loinc?: string[];
  /** Catalog ids (registry.json) this row is linked to. */
  catalog?: string[];
  /** Method-specific NČLP keys of the same item. */
  methods?: string[];
}

export interface LabCodeTable {
  schema: number;
  source: Record<string, unknown>;
  rows: LabCodeRow[];
}

export interface LabCodeHit {
  row: LabCodeRow;
  score: number;
  /** 2 same unit · 1 same kind of quantity (or unknown) · 0 disagrees. */
  unit: number;
  /** 2 same specimen · 1 same family (serum/plasma/blood) · 0 unknown. */
  material: number;
}

// ---------------------------------------------------------------- material

const BLOOD = new Set(["s", "p", "b"]);

/** Any specimen: a prefix we cannot read (X_ punctate, C_ …) is no evidence for blood. */
const ANY = new Set<string>(["*"]);

/** A printed prefix → the row materials it can mean. Null = no evidence. */
function materialSet(code: string | null | undefined): Set<string> | null {
  if (!code) return null;
  const out = new Set<string>();
  for (const c of code.split(",")) {
    if (c === "s" || c === "p" || c === "b" || c === "u" || c === "du") out.add(c);
    else if (c === "sp") (out.add("s"), out.add("p"));
    else if (c === "pk" || c === "k" || c === "pe" || c === "fw") out.add("b");
    else if (c === "fu" || c === "su") out.add("du"); // fU_ / sU_: collected urine
  }
  return out.size ? out : ANY;
}

/** -1 = incompatible (blood vs urine), else 0 unknown / 1 same family / 2 exact. */
function materialScore(rowMat: string, want: Set<string> | null): number {
  if (want === ANY) return 0;
  if (!want) return BLOOD.has(rowMat) ? 0 : -1; // no evidence: a blood report
  if (want.has(rowMat)) return 2;
  const fam = (m: string) => (BLOOD.has(m) ? "blood" : "urine");
  return [...want].some((w) => fam(w) === fam(rowMat)) ? 1 : -1;
}

// -------------------------------------------------------------------- unit

/** Fold a unit to one comparable spelling; "" for a dimensionless one. */
export function unitKey(u: string | null | undefined): string | null {
  if (u === null || u === undefined) return null;
  const c = canonicalizeUnit(u) ?? "";
  const s = c.toLowerCase().replace(/\s+/g, "");
  return s === "1" || s === "-" ? "" : s;
}

/** The kinds of quantity a printed unit can carry. */
export function unitProps(u: string | null | undefined): string[] | null {
  const k = unitKey(u);
  if (k === null) return null;
  // "G/l" and "T/l" (giga, tera per litre) are counts; lowercased, G/l would read as grams.
  if (/^\s*[GT]\/l\s*$/.test(u ?? "")) return ["NCnc"];
  if (k === "" || k === "%" || k === "ratio" || k === "index") {
    return ["NFr", "SFr", "MFr", "VFr", "CFr", "RelTime", "pH", "PrThr", "Prid", "ACnc", "Titr", "RelSCnc"];
  }
  if (/^[kmµnpf]?mol\/(l|kg)$/.test(k) || k === "mmol/mol") return k === "mmol/mol" ? ["SFr"] : ["SCnc"];
  if (/^[kmµnp]?g\/(l|dl|ml)$/.test(k)) return ["MCnc"];
  if (/kat\/l$/.test(k)) return ["CCnc"];
  if (/^(m|k)?i?u\/(l|ml)$/.test(k) || /^(au|ru|arb\.j\.|u)\/ml$/.test(k) || k === "arb.j.") return ["CCnc", "ACnc", "Titr"];
  if (/^10\^\d+\/l$/.test(k) || /^\/(µl|nl|l)$/.test(k)) return ["NCnc"];
  if (k === "fl") return ["EntVol"];
  if (k === "pg") return ["EntMass"];
  if (k === "s" || k === "min" || k === "minuta") return ["Time"];
  if (k === "kpa" || k === "mmhg") return ["PPres"];
  if (/\/(d|24h|den)$/.test(k)) return ["SRat", "MRat", "CRat"];
  if (k === "mm/h" || k === "mm/hod") return ["LENGTH"];
  return [];
}

function unitScore(row: LabCodeRow, printedUnit: string | null | undefined): number {
  const want = unitKey(printedUnit);
  if (want === null) return 1; // no unit printed: no evidence either way
  const have = unitKey(row.unit);
  if (have === want) return 2;
  // A fraction item ([1]) is the same quantity a lab prints as %.
  if (want === "%" && have === "" && /Fr$/.test(row.prop)) return 2;
  const props = unitProps(printedUnit);
  if (!props || props.length === 0) return 1; // a unit we cannot read: neutral
  return props.includes(row.prop) ? 1 : 0;
}

// -------------------------------------------------------------- name keys

/** Every key a printed name is looked up under, the full key first. */
export function nameKeys(name: string): string[] {
  const keys: string[] = [];
  const add = (s: string | null | undefined) => {
    const k = s ? normKey(s) : "";
    if (k && !keys.includes(k)) keys.push(k);
  };
  const raw = (name || "").trim();
  add(raw);
  const abbr = abbreviationKey(raw);
  if (abbr && !keys.includes(abbr)) keys.push(abbr);
  const lead = leadingCodeKey(raw);
  if (lead && !keys.includes(lead)) keys.push(lead);
  // "NA (Sodium)", "Bilirubin (celkový)": the part outside and inside.
  const paren = /^(.*?)\s*\(([^()]+)\)\s*$/.exec(raw);
  if (paren) (add(paren[1]), add(paren[2]));
  // "ALP - alkalická fosfatasa": abbreviation, spaced hyphen, long form.
  for (const part of raw.split(/\s+[-–]\s+/)) if (part !== raw) add(part);
  return keys;
}

function trigrams(s: string): Set<string> {
  const t = ` ${s} `;
  const out = new Set<string>();
  for (let i = 0; i + 3 <= t.length; i++) out.add(t.slice(i, i + 3));
  return out;
}

/** Trigram → the distinct name keys holding it; built on the first shortlist. */
interface GramIndex {
  keys: string[];
  size: Uint16Array;
  postings: Map<string, number[]>;
}

// ------------------------------------------------------------------ table

export interface LabCodesOptions {
  /** Merge these catalog entries' synonyms into the rows they are linked to. */
  catalog?: Pick<AnalyteDef, "canonicalId" | "synonyms">[];
  /** Languages whose names are indexed (default: all present). */
  languages?: string[];
  /** Index NČLP's own names only, not the catalog-lent `common` ones (measures the code list alone). */
  nclpOnly?: boolean;
}

export class LabCodes {
  readonly rows: LabCodeRow[];
  private readonly byKey = new Map<string, LabCodeRow[]>();
  private readonly byCode = new Map<string, LabCodeRow>();
  private readonly byLoincCode = new Map<string, LabCodeRow[]>();
  private readonly byCatalog = new Map<string, LabCodeRow[]>();
  private gramIndex: GramIndex | null = null;

  constructor(table: LabCodeTable, opts: LabCodesOptions = {}) {
    this.rows = table.rows;
    const extra = new Map<string, string[]>();
    for (const a of opts.catalog ?? []) extra.set(a.canonicalId, a.synonyms);
    for (const row of this.rows) {
      this.byCode.set(row.id, row);
      for (const m of row.methods ?? []) this.byCode.set(m, row);
      for (const l of row.loinc ?? []) this.push(this.byLoincCode, l, row);
      for (const c of row.catalog ?? []) this.push(this.byCatalog, c, row);
      const names: string[] = [];
      for (const [lang, n] of Object.entries(row.names)) {
        if (opts.languages && !opts.languages.includes(lang)) continue;
        names.push(...(n.printed ?? []), ...n.syn, ...(opts.nclpOnly ? [] : (n.common ?? [])));
      }
      for (const c of row.catalog ?? []) names.push(...(extra.get(c) ?? []));
      for (const k of new Set(names.map(normKey).filter(Boolean))) this.push(this.byKey, k, row);
    }
  }

  private grams(): GramIndex {
    if (this.gramIndex) return this.gramIndex;
    const keys = [...this.byKey.keys()];
    const size = new Uint16Array(keys.length);
    const postings = new Map<string, number[]>();
    keys.forEach((k, i) => {
      const g = trigrams(k);
      size[i] = g.size;
      for (const x of g) {
        const p = postings.get(x);
        if (p) p.push(i);
        else postings.set(x, [i]);
      }
    });
    return (this.gramIndex = { keys, size, postings });
  }

  private push<T>(m: Map<string, T[]>, k: string, v: T) {
    const a = m.get(k);
    if (!a) m.set(k, [v]);
    else if (!a.includes(v)) a.push(v);
  }

  /** A row by its NČLP key; a method-specific key resolves to its generic row. */
  byId(code: string): LabCodeRow | undefined {
    return this.byCode.get(code);
  }

  byLoinc(code: string): LabCodeRow[] {
    return this.byLoincCode.get(code) ?? [];
  }

  forCatalog(canonicalId: string): LabCodeRow[] {
    return this.byCatalog.get(canonicalId) ?? [];
  }

  /**
   * Exact-key lookup, ranked. `material` is the page's or the row's material
   * code when the name carries no prefix (normalize.ts MATERIAL_CODES).
   */
  lookup(name: string, unit?: string | null, material?: string | null): LabCodeHit[] {
    const want = materialSet(materialPrefix(name) ?? material ?? null);
    const keys = nameKeys(name);
    const seen = new Map<LabCodeRow, LabCodeHit>();
    keys.forEach((k, i) => {
      for (const row of this.byKey.get(k) ?? []) {
        const m = materialScore(row.mat, want);
        if (m < 0) continue;
        const u = unitScore(row, unit);
        // Ties: serum before plasma (the common Czech default), and a measured
        // item before a formula variant of it (Ca ionizované "Vzorec 1").
        const score = (i === 0 ? 3 : 2) + u + m + (row.mat === "s" ? 0.1 : 0) - (row.names.cs?.method ? 0.2 : 0);
        const prev = seen.get(row);
        if (!prev || prev.score < score) seen.set(row, { row, score, unit: u, material: m });
      }
    });
    return [...seen.values()].sort((a, b) => b.score - a.score || a.row.id.localeCompare(b.row.id));
  }

  /**
   * The `n` rows most like the printed name, for a model to choose from.
   * Rows of an incompatible specimen are never offered.
   */
  shortlist(name: string, unit?: string | null, material?: string | null, n = 20): LabCodeHit[] {
    const want = materialSet(materialPrefix(name) ?? material ?? null);
    const idx = this.grams();
    // Dice similarity of each query key against every name key sharing a
    // trigram with it; a row scores its best-matching key.
    const sim = new Map<LabCodeRow, number>();
    const shared = new Uint16Array(idx.keys.length);
    for (const qk of nameKeys(name)) {
      const g = trigrams(qk);
      shared.fill(0);
      const touched: number[] = [];
      for (const x of g) {
        for (const i of idx.postings.get(x) ?? []) {
          if (shared[i]++ === 0) touched.push(i);
        }
      }
      for (const i of touched) {
        const d = (2 * shared[i]) / (g.size + idx.size[i]);
        for (const row of this.byKey.get(idx.keys[i]) ?? []) {
          if ((sim.get(row) ?? 0) < d) sim.set(row, d);
        }
      }
    }
    for (const h of this.lookup(name, unit, material)) sim.set(h.row, 1);
    const hits: LabCodeHit[] = [];
    for (const [row, s] of sim) {
      const m = materialScore(row.mat, want);
      if (m < 0) continue;
      const u = unitScore(row, unit);
      hits.push({ row, score: s + 0.12 * u + 0.08 * m, unit: u, material: m });
    }
    hits.sort((a, b) => b.score - a.score || a.row.id.localeCompare(b.row.id));
    return hits.slice(0, n);
  }
}

/** The row fields a model needs to choose: code, name, specimen, quantity, unit. */
export function describeForModel(row: LabCodeRow, lang = "cs"): string {
  const n = row.names[lang] ?? row.names.cs;
  return `${row.id} | ${n.name} | ${row.spec} | ${row.prop} | ${row.unit}`;
}
